"I suggerimenti del coach si basano su principi consolidati di programmazione dell’allenamento e non costituiscono una valutazione medica. In presenza di patologie, dolori o dubbi su un referto, rivolgiti a un medico o a un professionista qualificato.": "Die Vorschläge des Coaches beruhen auf bewährten Prinzipien der Trainingsplanung und sind keine medizinische Beurteilung. Bei Erkrankungen, Schmerzen oder Fragen zu einem Befund wende dich an einen Arzt oder eine qualifizierte Fachkraft.",
"I tuoi allenamenti": "Deine Trainings",
