"Inspira nella fase eccentrica (quando il muscolo si allunga), espira nella fase concentrica (quando si accorcia e solleva il peso).": "Einatmen in der exzentrischen Phase (der Muskel wird länger), ausatmen in der konzentrischen Phase (er verkürzt sich und hebt das Gewicht).",
"Inspira profondamente e contrai l’addome prima della fase più difficile (con carichi alti puoi trattenere il fiato #–# secondi: manovra di Valsalva). Espira superato il punto più duro della salita.": "Tief einatmen und den Bauch anspannen vor der schwersten Phase (bei hohen Lasten kannst du #–# Sekunden die Luft anhalten: Valsalva-Manöver). Ausatmen, sobald der härteste Punkt überwunden ist.",
"Inspira, contrai l'addome e \"togli il gioco\" al bilanciere tirandolo verso di te.": "Einatmen, Bauch anspannen und das \"Spiel aus der Stange nehmen\", indem du sie zu dir ziehst.",
