"LUN": "MO",
"La bioimpedenziometria misura massa grassa, massa magra e acqua corporea: dice se stai perdendo grasso o muscolo, cosa che la bilancia da sola non sa fare. Carica il PDF e leggo io tutti i valori: peso compreso, non serve riscriverli.": "Die Bioimpedanzanalyse misst Fettmasse, Magermasse und Körperwasser: sie zeigt, ob du Fett oder Muskeln verlierst, was eine Waage allein nicht kann. Lade das PDF hoch und ich lese alle Werte, inklusive Gewicht: kein Abtippen nötig.",
