"Risali controllato fino a braccia distese.": "Komm kontrolliert hoch, bis die Arme gestreckt sind.",
"Risali controllato fino a gomiti a #°.": "Komm kontrolliert hoch, bis die Ellbogen bei #° sind.",
"Risali fino ad avere il corpo in linea retta.": "Komm hoch, bis der Körper eine gerade Linie bildet.",
"Risali lentamente finché senti i dorsali allungarsi.": "Komm langsam hoch, bis du den Latissimus dehnen spürst.",
"Risali lentamente fino a braccia distese, lasciando salire le scapole.": "Geh langsam zurück, bis die Arme gestreckt sind, und lass die Schulterblätter mitgehen.",
"Risali spingendo con il tallone della gamba davanti.": "Komm hoch, indem du über die Ferse des vorderen Beins drückst.",
"Risali spingendo con tutto il piede, non solo con le punte.": "Komm hoch und drück über den ganzen Fuß, nicht nur die Zehen.",
"Risali spingendo con tutto il piede.": "Komm hoch und drück über den ganzen Fuß.",
"Risali spingendo con tutto il piede: petto e anche salgono insieme.": "Komm hoch und drück über den ganzen Fuß: Brust und Hüfte steigen gemeinsam.",
"Risali spingendo fino a braccia distese.": "Drück dich hoch, bis die Arme gestreckt sind.",
