"Rotazione e spinta in un unico gesto fluido.": "Drehung und Drücken in einer fließenden Bewegung.",
"Rotola in avanti mantenendo il bacino in retroversione.": "Roll nach vorn und halte das Becken aufgerichtet.",
"Rullo delle cosce allentato.": "Oberschenkelpolster zu locker.",
"Ruota il busto da un lato all'altro portando le mani o il peso vicino al fianco.": "Dreh den Oberkörper von Seite zu Seite und bring Hände oder Gewicht neben die Hüfte.",
