"Sali fino all altezza delle spalle, non oltre.": "Heb bis auf Schulterhöhe, nicht höher.",
"Sali piegando solo l avambraccio.": "Komm hoch, indem du nur den Unterarm beugst.",
"Sali sulle punte il piu in alto possibile.": "Geh so hoch wie möglich auf die Zehenspitzen.",
