"Schiena": "Rücken",
"Schiena appoggiata a una panca, piedi ben piantati.": "Rücken an einer Bank, Füße fest am Boden.",
"Schiena appoggiata, ginocchio allineato al perno della macchina, rullo sopra le caviglie.": "Rücken angelehnt, Knie auf Höhe der Maschinenachse, Rolle über den Knöcheln.",
"Schiena arrotondata.": "Runder Rücken.",
"Schiena bassa": "Unterer Rücken",
"Schiena che sfiora la panca.": "Rücken streift die Bank.",
"Schiena che si arrotonda (flessione lombare) sotto carico.": "Rücken rundet sich (Lendenbeugung) unter Last.",
"Schiena che si arrotonda in fondo.": "Rücken rundet sich unten.",
"Schiena che si arrotonda per scendere più in basso.": "Rücken rundet sich, um tiefer zu kommen.",
"Schiena che si arrotonda.": "Rücken, der sich rundet.",
"Schiena curva: e l errore che fa male.": "Runder Rücken: das ist der Fehler, der wehtut.",
"Schiena e Bicipiti": "Rücken und Bizeps",
"Schiena e bacino ben appoggiati, piedi a metà pedana alla larghezza delle anche.": "Rücken und Becken gut angelehnt, Füße mittig auf der Plattform, hüftbreit.",
"Schiena e spalle ben appoggiate, piedi a metà pedana alla larghezza delle spalle.": "Rücken und Schultern gut angelehnt, Füße mittig auf der Plattform, schulterbreit.",
"Schiena lunga, non curva.": "Langer, nicht runder Rücken.",
"Schiena neutra": "Neutraler Rücken",
"Schienale a #°, manubri appoggiati sulle cosce per portarli su con una spinta delle ginocchia. Scapole strette e basse.": "Lehne auf #°, Hanteln auf den Oberschenkeln, um sie mit einem Kniestoß hochzubringen. Schulterblätter zusammen und unten.",
"Schienale a #°: oltre i #° lavora soprattutto la spalla. Scapole addotte e depresse, piedi saldi a terra.": "Lehne auf #°: über #° arbeitet vor allem die Schulter. Schulterblätter zurück- und heruntergezogen, Füße fest am Boden.",
"Schienale troppo alto: l'esercizio diventa uno shoulder press.": "Lehne zu steil: die Übung wird zum Schulterdrücken.",
"Scrivi un numero da # a #.": "Gib eine Zahl von # bis # ein.",
"Scrollate (Shrug)": "Schulterheben (Shrugs)",
"Scuro": "Dunkel",
"Sdraiato con occhi sotto il bilanciere. Cinque punti di contatto: testa, scapole e glutei sulla panca, piedi a terra. Scapole addotte e depresse (strette e portate verso il basso): creano una base stabile e proteggono la spalla.": "Liegend, Augen unter der Stange. Fünf Kontaktpunkte: Kopf, Schulterblätter und Gesäß auf der Bank, Füße am Boden. Schulterblätter zurück- und heruntergezogen: das schafft eine stabile Basis und schützt die Schulter.",
"Sdraiato sul fianco, corpo in linea, testa appoggiata sul braccio.": "Seitlich liegend, Körper in einer Linie, Kopf auf dem Arm.",
"Sdraiato sulla panca, manubrio tenuto a due mani sopra il petto, gomiti leggermente flessi.": "Auf der Bank liegend, Hantel mit beiden Händen über der Brust, Ellbogen leicht gebeugt.",
"Sdraiato, avvicina le scapole tra loro e abbassa le spalle.": "Liegend die Schulterblätter zusammenziehen und die Schultern senken.",
"Sdraiato, bilanciere EZ o manubri sopra il petto, braccia leggermente inclinate verso la testa.": "Liegend, SZ-Stange oder Kurzhanteln über der Brust, Arme leicht zum Kopf geneigt.",
"Sdraiato, manubri sopra il petto con palmi che si guardano, gomiti leggermente flessi e fissi.": "Liegend, Hanteln über der Brust mit Handflächen zueinander, Ellbogen leicht gebeugt und fixiert.",
"Se con il silenzioso non senti nulla, affidati al lampeggio.": "Wenn du im Lautlos-Modus nichts hörst, verlass dich aufs Blinken.",
"Se la schiena si inarca, piega un po' le ginocchia.": "Wenn der Rücken ins Hohlkreuz geht, beug die Knie etwas.",
"Se non acconsenti, l’app funziona comunque: crei e segui i tuoi allenamenti in autonomia. Puoi cambiare scelta in qualsiasi momento dalle Opzioni.": "Wenn du nicht einwilligst, funktioniert die App trotzdem: du erstellst und verfolgst deine Trainings selbst. Du kannst deine Wahl jederzeit in den Einstellungen ändern.",
"Se non parte da sola, tocca ▶ sul lettore": "Wenn sie nicht von selbst startet, tippe ▶ im Player",
"Se non scegli nessuna canzone, durante il cedimento continua la musica che stai già ascoltando (Spotify, Apple Music…).": "Wenn du keinen Song wählst, läuft beim Muskelversagen die Musik weiter, die du schon hörst (Spotify, Apple Music…).",
