"Sedere troppo alto o troppo basso.": "Zu hoch oder zu tief sitzen.",
"Sedersi sui talloni per usare il peso del corpo.": "Sich auf die Fersen setzen, um das Körpergewicht zu nutzen.",
"Sedile regolato con le maniglie all'altezza del petto, schiena appoggiata, scapole strette.": "Sitz so eingestellt, dass die Griffe auf Brusthöhe sind, Rücken angelehnt, Schulterblätter zusammen.",
"Sedile regolato con le maniglie all'altezza delle spalle, schiena appoggiata.": "Sitz so eingestellt, dass die Griffe auf Schulterhöhe sind, Rücken angelehnt.",
"Sedile regolato male.": "Sitz falsch eingestellt.",
"Sedile troppo basso o alto: le spalle lavorano al posto del petto.": "Sitz zu tief oder zu hoch: Die Schultern arbeiten statt der Brust.",
"Seduta": "Einheit",
"Seduta nella norma: il programma prosegue come previsto.": "Normale Einheit: Das Programm läuft wie geplant weiter.",
"Sedute": "Einheiten",
"Seduto con schienale quasi verticale, manubri all'altezza delle spalle, palmi avanti o leggermente ruotati.": "Sitzend mit fast senkrechter Lehne, Kurzhanteln auf Schulterhöhe, Handflächen nach vorn oder leicht gedreht.",
"Seduto, busto inclinato indietro a circa #°, ginocchia piegate, piedi a terra o sollevati.": "Sitzend, Oberkörper etwa #° nach hinten geneigt, Knie gebeugt, Füße am Boden oder angehoben.",
"Seduto, ginocchia a #° sotto il rullo, avampiedi sulla pedana.": "Sitzend, Knie im #°-Winkel unter dem Polster, Fußballen auf der Plattform.",
"Seduto, ginocchia allineate al perno, rullo sopra le cosce ben stretto, rullo inferiore sotto i polpacci.": "Sitzend, Knie auf Höhe der Drehachse, Oberschenkelpolster fest, unteres Polster unter den Waden.",
"Seduto, gomito appoggiato all'interno della coscia, manubrio in mano.": "Sitzend, Ellbogen an der Innenseite des Oberschenkels abgestützt, Kurzhantel in der Hand.",
"Seduto, manubri davanti al viso con i palmi verso di te.": "Sitzend, Kurzhanteln vor dem Gesicht, Handflächen zu dir.",
"Seduto, piedi sulla pedana, ginocchia leggermente flesse, busto dritto, presa neutra.": "Sitzend, Füße auf der Plattform, Knie leicht gebeugt, Oberkörper aufrecht, neutraler Griff.",
"Seduto, schiena appoggiata, cuscinetti sull'esterno delle ginocchia.": "Sitzend, Rücken angelehnt, Polster an der Außenseite der Knie.",
