"Sotto il #% di massa grassa la funzione mestruale puo risentirne: e un valore da monitorare con un medico.": "Unter #% Körperfett kann der Menstruationszyklus beeinträchtigt werden: ein Wert, den man ärztlich beobachten sollte.",
"Sotto la mezz ora lo stimolo rischia di essere scarso, oltre i novanta minuti il recupero peggiora. Decido quanti esercizi metterti in base a questo.": "Unter einer halben Stunde ist der Reiz oft zu gering, über neunzig Minuten leidet die Erholung. Danach entscheide ich, wie viele Übungen du bekommst.",
"Sotto le": "Unter",
"Spalla": "Schulter",
"Spalla che sale verso l'orecchio.": "Schulter wandert Richtung Ohr.",
"Spalle": "Schultern",
"Spalle \"in tasca\": basse e indietro per tutta la discesa.": "Schultern „in die Hosentaschen\": tief und hinten während des ganzen Absenkens.",
"Spalle \\\"in tasca\\\": basse e indietro per tutta la discesa.": "Schultern \\\"in die Hosentaschen\\\": tief und hinten während des ganzen Absenkens.",
"Spalle basse mentre spingi.": "Schultern tief, während du drückst.",
"Spalle che salgono verso le orecchie.": "Schultern wandern Richtung Ohren.",
"Spalle che si portano in avanti a fine movimento.": "Schultern rollen am Bewegungsende nach vorn.",
"Spalle sopra le mani per tutta la serie.": "Schultern über den Händen während des ganzen Satzes.",
"Spento: serve il consenso ai dati": "Aus: Datenschutz-Einwilligung erforderlich",
"Spingere con la gamba dietro.": "Mit dem hinteren Bein drücken.",
"Spingere con le punte dei piedi.": "Über die Zehenspitzen drücken.",
"Spingere in avanti invece che in alto.": "Nach vorn statt nach oben drücken.",
"Spingi con i gomiti, non con le mani.": "Drücke mit den Ellbogen, nicht mit den Händen.",
"Spingi con i talloni e porta le anche in alto fino all'estensione completa: in alto le tibie sono verticali.": "Drücke über die Fersen und bringe die Hüfte in volle Streckung: Oben stehen die Schienbeine senkrecht.",
"Spingi con i talloni e solleva il bacino fino ad allineare spalle, anche e ginocchia.": "Drücke über die Fersen und hebe das Becken, bis Schultern, Hüfte und Knie eine Linie bilden.",
"Spingi con il palmo vicino al polso, non con le dita.": "Drücke mit dem Handballen, nicht mit den Fingern.",
"Spingi con il piede avanti per risalire.": "Drücke dich mit dem vorderen Fuß wieder hoch.",
"Spingi con il piede sulla panca fino a stare in piedi sopra.": "Drücke dich mit dem Fuß auf der Bank hoch, bis du oben stehst.",
"Spingi con il tallone della gamba avanti per tornare alla posizione iniziale.": "Drücke über die vordere Ferse zurück in die Ausgangsposition.",
"Spingi con tutto il piede senza bloccare di colpo le ginocchia in alto.": "Drücke mit dem ganzen Fuß, ohne oben die Knie ruckartig durchzustrecken.",
"Spingi con tutto il piede.": "Drücke mit dem ganzen Fuß.",
"Spingi convergendo leggermente verso l'alto, senza far sbattere i manubri.": "Drücke leicht zusammenlaufend nach oben, ohne die Hanteln zusammenzuschlagen.",
"Spingi e porta avanti l'altra gamba nel passo successivo.": "Drücke ab und bringe das andere Bein in den nächsten Schritt.",
"Spingi fino a braccia distese, traiettoria quasi verticale.": "Drücke bis zu gestreckten Armen, Bahn fast senkrecht.",
"Spingi fino a braccia distese.": "Drücke bis zu gestreckten Armen.",
"Spingi i manubri in alto convergendo leggermente.": "Drücke die Kurzhanteln leicht zusammenlaufend nach oben.",
