"Non trattenere il fiato: espira mentre sollevi, inspira in discesa. Carichi moderati, 8–12 ripetizioni.": "Halte nicht die Luft an: beim Heben ausatmen, beim Senken einatmen. Moderate Gewichte, 8–12 Wiederholungen.",
