"Il coach usa l’angolo di fase e l’acqua extracellulare solo per essere prudente all’inizio, non per scegliere i carichi.": "Der Coach nutzt Phasenwinkel und extrazelluläres Wasser nur, um am Anfang vorsichtig zu sein, nicht um die Gewichte zu wählen.",
