"Limite alto": "Obere Grenze",
"Il coach usa l’angolo di fase e l’acqua extracellulare solo per essere prudente all’inizio, non per scegliere i carichi. Se un valore è fuori norma, ripeti la misura a digiuno e a riposo.": "Der Coach nutzt Phasenwinkel und extrazelluläres Wasser nur, um am Anfang vorsichtig zu sein, nicht um die Gewichte zu wählen. Liegt ein Wert außerhalb der Norm, wiederhole die Messung nüchtern und in Ruhe.",
